    @Override
    public BaseResponse< List<UserDTO>> findAll(
            String code,
            LocalDate fromDate,
            LocalDate toDate,
            String phone,
            Pageable pageable) {
        if(StringUtils.isEmpty(code)){
            code = null;
        }
        if(StringUtils.isEmpty(fromDate)){
            fromDate = null;
        }
        if(StringUtils.isEmpty(toDate)){
            toDate = null;
        }
        if(StringUtils.isEmpty(phone)){
            phone = null;
        }

        Page<UserEntity> pageUserEntities = userRepository.findByCondition(code, fromDate, toDate, phone, pageable);
      List<UserDTO> userDTOs = new ArrayList<>();
      userDTOs = pageUserEntities.stream().map(entity -> userMapper.toDTO(entity)).toList();
        BaseResponse<List<UserDTO>> response = new BaseResponse<>();
        response.setData(userDTOs);
        response.setMessage("Success");
        response.setCode(HttpStatus.OK.value());
        response.setTotalElement(pageUserEntities.getTotalElements());
        response.setTotalPage(pageUserEntities.getTotalPages());
        response.setPageSize(pageable.getPageSize());
        response.setPageIndex(pageable.getPageNumber());
        return response;
    }


